sql:
select t1.x, t1.y
from (
    select (case when x < 100 then null else 99 end) x, (case when x < 100 then 99 else 99 end) y
    from tt2
) t1 left join tt2 t2
on t1.x < t2.x and t1.y < t2.x
order by t1.x nulls first, t1.y nulls first;

SELECT l.a, r.b
FROM pair_l l
FULL OUTER JOIN pair_r r ON EXISTS (
	SELECT 1 FROM pair_s s WHERE s.a = l.a AND s.b = r.b
)
ORDER BY l.a NULLS LAST, r.b NULLS LAST;

SELECT l.a, r.b
FROM pair_l l
FULL OUTER JOIN pair_r r ON r.b IN (
	SELECT s.b FROM pair_s s WHERE s.a = l.a
)
ORDER BY l.a NULLS LAST, r.b NULLS LAST;

SELECT l.a, r.b
FROM pair_l l
FULL OUTER JOIN pair_r r ON NOT EXISTS (
	SELECT 1 FROM pair_s s WHERE s.a = l.a AND s.b = r.b
)
ORDER BY l.a NULLS LAST, r.b NULLS LAST;

SELECT l.a, r.b
FROM pair_nested_l l
FULL OUTER JOIN pair_nested_r r ON EXISTS (
	SELECT 1
	WHERE EXISTS (
		SELECT 1 FROM pair_split_l sl WHERE sl.a = l.a
	)
	AND EXISTS (
		SELECT 1 FROM pair_split_r sr WHERE sr.b = r.b
	)
)
ORDER BY l.a NULLS LAST, r.b NULLS LAST;

SELECT l.a, r.b
FROM pair_nested_l l
FULL OUTER JOIN pair_nested_r r ON EXISTS (
	SELECT 1
	WHERE EXISTS (
		SELECT 1 FROM pair_split_l sl WHERE sl.a = l.a
	)
	OR EXISTS (
		SELECT 1 FROM pair_split_r sr WHERE sr.b = r.b
	)
)
ORDER BY l.a NULLS LAST, r.b NULLS LAST;

SELECT l.a, r.b
FROM pair_l l
FULL OUTER JOIN pair_r r ON EXISTS (
	SELECT 1 FROM pair_s s WHERE s.a = l.a AND s.b = r.b
) AND random() >= 0
ORDER BY l.a NULLS LAST, r.b NULLS LAST;

SELECT l.a, r.b
FROM pair_l l
FULL OUTER JOIN pair_r r ON EXISTS (
	SELECT 1 FROM pair_s s WHERE s.a = l.a AND s.b = r.b AND random() >= 0
)
ORDER BY l.a NULLS LAST, r.b NULLS LAST;

SELECT l.a, l.x, r.b
FROM pair_l l
LEFT JOIN pair_r r ON EXISTS (
	SELECT 1 FROM pair_s s WHERE s.a = l.a AND s.b = r.b
)
ORDER BY l.x, r.b NULLS LAST;

SELECT l.a, l.x, r.b
FROM pair_l l
LEFT JOIN pair_r r ON l.a IN (
	SELECT s.a FROM pair_s s WHERE s.b = r.b
)
ORDER BY l.x, r.b NULLS LAST;

SELECT l.a, l.x, r.b
FROM pair_l l
LEFT JOIN pair_r r ON r.b IN (
	SELECT s.b FROM pair_s s WHERE s.a = l.a
)
ORDER BY l.x, r.b NULLS LAST;

SELECT l.a, l.x, r.b
FROM pair_l l
LEFT JOIN pair_r r ON l.x > 10 AND r.b IN (
	SELECT s.b FROM pair_s s WHERE s.a = l.a
)
ORDER BY l.x, r.b NULLS LAST;

SELECT l.a, l.x, r.b
FROM pair_l l
LEFT JOIN pair_r r ON r.b NOT IN (
	SELECT s.b FROM pair_s s WHERE s.a = l.a
)
ORDER BY l.a, l.x, r.b NULLS LAST;

SELECT l.a, l.x, r.b
FROM pair_l l
LEFT JOIN pair_r r ON r.b = (
	SELECT max(s.b) FROM pair_s s WHERE s.a = l.a AND s.b <= r.b
)
ORDER BY l.a, l.x, r.b NULLS LAST;

SELECT l.a, l.x, r.b
FROM pair_l l
LEFT JOIN pair_r r ON CASE WHEN l.x > 10 THEN r.b ELSE NULL END = (
	SELECT s.b FROM pair_s s WHERE s.a = l.a AND s.b = r.b LIMIT 1
)
ORDER BY l.a, l.x, r.b NULLS LAST;

SELECT l.a, l.x, r.b
FROM pair_l l
RIGHT JOIN pair_r r ON EXISTS (
	SELECT 1 FROM pair_s s WHERE s.a = l.a AND s.b = r.b
)
ORDER BY r.b, l.x NULLS LAST;

SELECT l.a, l.x, r.b
FROM pair_l l
RIGHT JOIN pair_r r ON EXISTS (
	SELECT 1 FROM pair_s s WHERE s.a = l.a AND s.b = r.b
)
ORDER BY r.b, l.x NULLS LAST;

SELECT *
FROM pair_l l
RIGHT JOIN pair_r r ON EXISTS (
	SELECT 1 FROM pair_s s WHERE s.a = l.a AND s.b = r.b
)
ORDER BY r.b, l.x NULLS LAST;
